import {TODAY,money,dayAdd,dateLabel,seed,requireManager,accessibleJobs,getJob,saveCustomer,archiveCustomer,addStaff,saveJob,updateJob,createInvoice,markPaid,metrics,csv,validateState} from './domain.js';
const $=s=>document.querySelector(s), key='quenvira-demo-v1';
let state,storageWarning='';try{const saved=localStorage.getItem(key);state=saved?JSON.parse(saved):seed();if(!validateState(state))throw Error('Invalid saved state')}catch{state=seed();storageWarning='Saved data could not be loaded. A fresh demo is shown; export a backup before leaving.'}
let actor={role:'manager'},view='dashboard',selectedDate=TODAY,search='',filter='All',weekStart=dayAdd(TODAY,-1);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={dashboard:'▦',schedule:'▤',jobs:'✓',customers:'♧',team:'♙',invoices:'£',settings:'⚙'};
const customer=id=>state.customers.find(c=>c.id===id)||{name:'Archived customer',address:'',notes:''};
const staff=id=>state.staff.find(s=>s.id===id);
const initials=name=>name.split(' ').map(n=>n[0]).slice(0,2).join('');
const badge=status=>`<span class="badge ${esc(status.toLowerCase().replaceAll(' ','-'))}"><span class="dot"></span>${esc(status)}</span>`;
const button=(text,action,extra='',cls='')=>`<button type="button" class="${cls}" data-action="${action}" ${extra}>${text}</button>`;
const empty=(title,sub)=>`<div class="empty"><span>◌</span><h3>${title}</h3><p>${sub}</p></div>`;
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('visible'),4500)}
function persist(){try{localStorage.setItem(key,JSON.stringify(state));storageWarning=''}catch{storageWarning='Browser storage is unavailable or full. Changes are only held in memory. Export a backup before leaving.';toast(storageWarning)}}
function mutate(fn){const before=structuredClone(state);try{const result=fn();persist();return result}catch(e){state=before;throw e}}
function nav(){const items=actor.role==='manager'?['dashboard','schedule','jobs','customers','team','invoices','settings']:['jobs','schedule','settings'];return `<aside class="sidebar"><a class="brand" href="#dashboard"><img src="icon.svg" alt="" width="38" height="38">Quenvira</a><div class="workspace"><span class="avatar mint">F</span><div>Fern & Co. Cleaning<small>Fictional demo workspace</small></div></div><div class="navlabel">WORKSPACE</div><nav aria-label="Main navigation">${items.map(v=>`<a href="#${v}" class="${view===v?'active':''}" ${view===v?'aria-current="page"':''}><span>${icons[v]}</span>${{dashboard:'Overview',schedule:'Schedule',jobs:'Jobs',customers:'Customers',team:'Team',invoices:'Invoices',settings:'Demo & settings'}[v]}${v==='jobs'?`<small>${accessibleJobs(state,actor).filter(j=>j.date===TODAY&&j.status!=='Cancelled').length}</small>`:''}</a>`).join('')}</nav><div class="sidebar-note"><span>✧</span><strong>A little less admin.<br>A lot more clarity.</strong><p>Your business,<br>running smoothly.</p></div><div class="profile"><span class="avatar">${actor.role==='manager'?'JD':initials(staff(actor.staffId)?.name||'Team member')}</span><div>${actor.role==='manager'?'Jamie Dawson':esc(staff(actor.staffId)?.name)}<small>${actor.role==='manager'?'Demo manager':'Demo team member'}</small></div></div></aside>`}
function render(){const manager=actor.role==='manager';if(!manager&&!['jobs','schedule','settings'].includes(view))view='jobs';$('#app').innerHTML=`${nav()}<div class="main-wrap"><header class="topbar"><span class="crumb">Workspace <span>/</span> ${{dashboard:'Overview',schedule:'Schedule',jobs:'Jobs',customers:'Customers',team:'Team',invoices:'Invoices',settings:'Demo & settings'}[view]}</span><div class="top-actions"><span class="demo-pill">FICTIONAL DATA · DEMO</span><label class="sr" for="persona">Demo role</label><select id="persona" aria-label="Switch demo role"><option value="manager" ${manager?'selected':''}>Manager view</option>${state.staff.map(s=>`<option value="${esc(s.id)}" ${actor.staffId===s.id?'selected':''}>${esc(s.name)} · staff</option>`).join('')}</select></div></header><main id="main" tabindex="-1">${storageWarning?`<div role="alert" class="warning">${esc(storageWarning)}</div>`:''}${({dashboard:dashboard,schedule:schedule,jobs:jobsPage,customers:customersPage,team:teamPage,invoices:invoicesPage,settings:settingsPage}[view])()}</main><footer>Quenvira demonstration <span>•</span> Fictional records only <span>•</span> Demo clock: 20 October 2026</footer></div>`;$('#persona').addEventListener('change',e=>{actor=e.target.value==='manager'?{role:'manager'}:{role:'staff',staffId:e.target.value};if(actor.role==='staff')view='jobs';search='';filter='All';render()});bindPage();}
function heading(eyebrow,title,subtitle,actions=''){return `<div class="page-heading"><div><p class="eyebrow">${eyebrow}</p><h1>${title}</h1><p>${subtitle}</p></div><div class="actions">${actions}</div></div>`}
function stat(label,value,note,icon,cls=''){return `<section class="stat ${cls}"><div>${label}<span>${icon}</span></div><strong>${value}</strong><small>${note}</small></section>`}
function person(id){const s=staff(id);return s?`<span class="person"><span class="avatar ${esc(s.colour)}">${esc(initials(s.name))}</span>${esc(s.name)}</span>`:`<span class="unassigned">Unassigned</span>`}
function jobTable(jobs){return jobs.length?`<div class="table-wrap"><table><thead><tr><th>Customer / service</th><th>Time & duration</th><th>Team member</th><th>Status</th>${actor.role==='manager'?'<th>Value</th>':''}<th><span class="sr">Open</span></th></tr></thead><tbody>${jobs.sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time)).map(j=>`<tr><td><button class="text-button customer-name" data-action="job-detail" data-id="${esc(j.id)}">${esc(customer(j.customerId).name)}</button><small>${esc(j.round)} · ${esc(j.repeat)}</small></td><td><strong>${esc(j.time)}</strong> <small>${j.duration/60}h · ${esc(dateLabel(j.date))}</small></td><td>${person(j.staffId)}</td><td>${badge(j.status)}</td>${actor.role==='manager'?`<td class="amount">${money(j.price)}</td>`:''}<td>${button('↗','job-detail',`data-id="${esc(j.id)}" aria-label="Open ${esc(customer(j.customerId).name)} job"`,'icon-button')}</td></tr>`).join('')}</tbody></table></div>`:empty('No jobs here','Try another day or change your filters.')}
function dashboard(){const m=metrics(state),today=state.jobs.filter(j=>j.date===TODAY&&j.status!=='Cancelled');return heading('TUESDAY, 20 OCTOBER 2026','A clearer day starts here.','Here’s what’s happening at Fern & Co. today.',button('＋ New job','new-job','','primary'))+`<div class="stats">${stat('Jobs today',m.today,`${m.completed} completed · ${m.today-m.completed} to go`,'▤')}${stat('Scheduled value',money(m.scheduledValue),'Today’s booked work, excluding VAT','↗')}${stat('Outstanding invoices',money(m.outstanding),`${state.invoices.filter(i=>i.status!=='Paid').length} unpaid demo invoices`,'£')}${stat('Needs assigning',m.unassigned,'Upcoming visits without a team member','♙','attention')}</div><section class="day-banner"><div class="banner-icon">✦</div><div><h2>Good teams deserve a smoother day.</h2><p>Plan the round. Deliver the clean. Keep everything moving.</p></div><a href="#schedule">Open schedule <span>↗</span></a></section><div class="dashboard-grid"><section class="panel"><div class="panel-head"><div><h2>Today’s jobs <span class="count">${today.length}</span></h2><p>A shared plan, from the first door to the last.</p></div><a href="#jobs">View all jobs →</a></div>${jobTable(today)}</section><section class="panel round-panel"><div class="panel-head"><div><h2>Round progress</h2><p>Today, at a glance</p></div><span>◴</span></div>${[...new Set(today.map(j=>j.round))].map((r,i)=>{const list=today.filter(j=>j.round===r),done=list.filter(j=>j.status==='Completed').length;return `<div class="round"><div><span class="round-symbol c${i}">↻</span><strong>${esc(r)}</strong></div><progress value="${done}" max="${list.length}" aria-label="${esc(r)} completion"></progress><small>${done} of ${list.length} complete <span>${money(list.reduce((a,j)=>a+j.price,0))}</span></small></div>`}).join('')}<div class="quiet-note">${m.unassigned?`${m.unassigned} upcoming visit needs a team member.`:'All upcoming visits have an assigned team member.'} <a href="#jobs">Review jobs →</a></div></section></div><div class="dashboard-grid bottom-grid"><section class="panel"><div class="panel-head"><div><h2>Your team today</h2><p>A balanced workload makes a better day.</p></div><a href="#team">Manage team →</a></div><div class="team-strip">${state.staff.map(s=>{const js=today.filter(j=>j.staffId===s.id),mins=js.reduce((a,j)=>a+j.duration,0);return `<div>${person(s.id)}<small>${js.length} visits · ${mins/60}h / ${s.capacity/60}h capacity</small><progress value="${mins}" max="${s.capacity}" aria-label="${esc(s.name)} workload"></progress></div>`}).join('')}</div></section><section class="panel insight"><p class="eyebrow">THE QUENVIRA WAY</p><h2>Small details.<br>Consistently great cleans.</h2><p>Every visit has its own checklist, customer instructions and completion record.</p><a href="#jobs">See the workflow →</a></section></div>`}
function jobsPage(){let list=accessibleJobs(state,actor).filter(j=>j.date===selectedDate);if(filter!=='All')list=list.filter(j=>filter==='Unassigned'?!j.staffId:j.status===filter);if(search)list=list.filter(j=>(customer(j.customerId).name+' '+j.round).toLowerCase().includes(search.toLowerCase()));return heading('WORK, WITHOUT THE GUESSWORK',actor.role==='manager'?'Every job, in order.':'Your jobs. Your day.','Open a visit to follow the checklist and record your progress.',actor.role==='manager'?button('＋ New job','new-job','','primary'):'')+`<section class="panel"><div class="toolbar"><div class="date-control">${button('‹','prev-day','aria-label="Previous day"','icon-button')}<input id="job-date" type="date" value="${selectedDate}" aria-label="Job date">${button('›','next-day','aria-label="Next day"','icon-button')}${button('Demo today','today','','small-button')}</div><input id="job-search" type="search" placeholder="Search customers or rounds" value="${esc(search)}" aria-label="Search jobs"></div><div class="tabs" role="group" aria-label="Filter jobs">${['All','Scheduled','In progress','Completed','Cancelled','Unassigned'].map(v=>button(v,'filter',`data-value="${v}" aria-pressed="${filter===v}"`,filter===v?'selected':'')).join('')}</div>${jobTable(list)}</section>`}
function schedule(){const dates=Array.from({length:7},(_,i)=>dayAdd(weekStart,i)),all=accessibleJobs(state,actor);return heading('ROOM FOR A BETTER ROUTINE','The week, well planned.','Select any visit to see the details. Recurring visits are booked as a finite series.',actor.role==='manager'?button('＋ Plan a visit','new-job','','primary'):'')+`<div class="schedule-tools"><div>${button('← Previous','prev-week')}<strong>${dateLabel(dates[0])} – ${dateLabel(dates[6])}</strong>${button('Next →','next-week')}</div><span class="muted">Times shown in UK local time</span></div><div class="week-grid">${dates.map(d=>`<section class="day-column ${d===TODAY?'today':''}"><header><span>${dateLabel(d).split(',')[0]}</span><strong>${new Date(d).getUTCDate()}</strong><small>${all.filter(j=>j.date===d&&j.status!=='Cancelled').length} visits</small></header>${all.filter(j=>j.date===d&&j.status!=='Cancelled').sort((a,b)=>a.time.localeCompare(b.time)).map(j=>`<button class="visit-card ${esc(staff(j.staffId)?.colour||'orange')}" data-action="job-detail" data-id="${esc(j.id)}"><span>${esc(j.time)} · ${j.duration/60}h</span><strong>${esc(customer(j.customerId).name)}</strong><small>${esc(j.round)}</small><span class="visit-person">${esc(staff(j.staffId)?.name||'Needs assigning')}</span>${badge(j.status)}</button>`).join('')||'<p class="free-day">Room to breathe</p>'}</section>`).join('')}</div>`}
function customersPage(){const list=state.customers.filter(c=>c.active&&(c.name+' '+c.address).toLowerCase().includes(search.toLowerCase()));return heading('GOOD SERVICE STARTS WITH KNOWING PEOPLE','Customers, cared for.','Contact details, preferences and visit history in one place.',button('＋ Add customer','new-customer','','primary'))+`<section class="panel"><div class="toolbar"><strong>${list.length} active customers</strong><input type="search" id="customer-search" placeholder="Find a customer" aria-label="Search customers" value="${esc(search)}"></div><div class="customer-grid">${list.map(c=>`<article class="customer-card"><div class="card-top"><span class="avatar large ${c.type==='Commercial'?'blue':'green'}">${esc(initials(c.name))}</span><span class="type-label">${esc(c.type)}</span></div><h2>${esc(c.name)}</h2><p>${esc(c.address)}</p><small>${esc(c.email||'No email on file')}</small><div class="card-note">${esc(c.notes||'No preferences recorded.')}</div><div class="card-bottom"><span>${state.jobs.filter(j=>j.customerId===c.id&&j.status==='Completed').length} completed visits</span>${button('View & edit →','customer-detail',`data-id="${esc(c.id)}"`,'text-button')}</div></article>`).join('')||empty('No matching customers','Try a different search or add your first fictional customer.')}</div></section>`}
function teamPage(){return heading('A GREAT CLEAN IS A TEAM EFFORT','People behind the polish.','Daily capacity and workload for the demo day.',button('＋ Add team member','new-staff','','primary'))+`<div class="staff-grid">${state.staff.map(s=>{const js=state.jobs.filter(j=>j.staffId===s.id&&j.date===TODAY&&j.status!=='Cancelled'),minutes=js.reduce((a,j)=>a+j.duration,0);return `<section class="panel staff-card"><span class="avatar large ${esc(s.colour)}">${esc(initials(s.name))}</span><h2>${esc(s.name)}</h2><p>${esc(s.role)}</p><div class="staff-stats"><div><strong>${js.length}</strong><small>Visits today</small></div><div><strong>${minutes/60}h</strong><small>Scheduled time</small></div></div><progress value="${minutes}" max="${s.capacity}" aria-label="Daily workload"></progress><small>${s.capacity/60}h daily capacity · ${Math.round(minutes/s.capacity*100)}% booked</small>${button('Preview staff view','staff-view',`data-id="${esc(s.id)}"`,'full')}</section>`}).join('')}</div><div class="notice">Staff views demonstrate assigned work only. This switch is a demo tool, not a secure sign-in system.</div>`}
function invoicesPage(){const m=metrics(state);return heading('CLEAN WORK. CLEAR BOOKS.','Keep the numbers simple.','Draft invoices from completed jobs. No emails or payments are sent.',button('↓ Export invoices','export-invoices'))+`<div class="stats three">${stat('Paid invoices',money(m.paid),'Manually recorded demo payments','✓')}${stat('Outstanding',money(m.outstanding),'All unpaid invoices, including drafts','£')}${stat('Ready to invoice',state.jobs.filter(j=>j.status==='Completed'&&!j.invoiceId).length,'Completed visits without an invoice','↗')}</div><section class="panel"><div class="panel-head"><h2>Invoices</h2>${button('＋ Create invoice','new-invoice','','primary')}</div>${state.invoices.length?`<div class="table-wrap"><table><thead><tr><th>Invoice</th><th>Customer</th><th>Due date</th><th>Status</th><th>Total</th><th>Actions</th></tr></thead><tbody>${state.invoices.map(i=>`<tr><td><strong>${esc(i.number)}</strong><small>Issued ${dateLabel(i.issued)}</small></td><td>${esc(i.customerName)}</td><td>${dateLabel(i.due)}</td><td>${badge(i.status)}${i.status!=='Paid'&&i.due<TODAY?'<small class="overdue">Past due date</small>':''}</td><td class="amount">${money(i.total)}</td><td>${button('View','invoice-detail',`data-id="${esc(i.id)}"`,'small-button')}</td></tr>`).join('')}</tbody></table></div>`:empty('No invoices yet','Complete a visit, then create its invoice.')}</section>`}
function settingsPage(){return heading('A SAFE SPACE TO EXPLORE','Meet your demonstration.','Use fictional information only. Nothing here contacts customers.')+`<div class="settings-grid"><section class="panel padded"><h2>What this demo does</h2><p>Explore customer management, weekly planning, recurring visits, staff allocation, job checklists and draft invoicing.</p><p>Changes stay in this browser on this device. This is not a shared database. Private browsing or clearing site data can remove your changes.</p><p>The demo clock is fixed to <strong>20 October 2026</strong> so the example always tells the same story.</p><h3>Try the whole journey</h3><ol><li>Add a fictional customer.</li><li>Book a visit and assign a team member.</li><li>Open the job, start it and tick the checklist.</li><li>Complete the job, then create an invoice.</li><li>Record a manual demo payment.</li></ol></section><section class="panel padded"><h2>Before real customer use</h2><p>This demonstration has no production authentication, server-enforced tenant isolation, backups, payment processing, email delivery or accounting integration. Staff role previews are not a security boundary.</p><p>Do not enter addresses, access codes, health details, or any other real personal information. The records shown are invented.</p><h3>Demo data controls</h3>${actor.role==='manager'?`<div class="stack">${button('↓ Download JSON backup','export-json')}${button('↓ Export customer CSV','export-customers')}${button('Reset fictional demonstration','reset','','danger')}</div>`:'<p>Switch to manager view for export and reset tools.</p>'}<p class="muted">Reset removes this browser’s edits and restores the fictional examples. Downloaded exports remain on your device.</p></section></div><section class="panel padded"><h2>Recent demo activity</h2>${state.audit.length?`<ul class="activity">${state.audit.filter(a=>actor.role==='manager'||a.actor===actor.staffId).slice(0,20).map(a=>`<li><span>${esc(a.message)}</span><small>${esc(a.actor)} · ${new Date(a.at).toLocaleString('en-GB')}</small></li>`).join('')}</ul>`:'<p class="muted">Your actions will appear here as you explore.</p>'}</section>`}
function modal(title,body){const d=$('#modal');d.innerHTML=`<header><div><p class="eyebrow">QUENVIRA · DEMO</p><h2 id="modal-title">${esc(title)}</h2></div>${button('×','close','aria-label="Close dialog"','icon-button')}</header><div class="modal-body">${body}</div>`;if(!d.open)d.showModal();bindModal();}
function field(label,name,value='',type='text',extra=''){return `<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`}
function select(label,name,options,value){return `<label>${label}<select name="${name}">${options.map(([v,t])=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(t)}</option>`).join('')}</select></label>`}
function formEnd(label='Save changes'){return `<p id="form-error" class="form-error" role="alert"></p><div class="form-footer">${button('Cancel','close')}<button type="submit" class="primary">${label}</button></div></form>`}
function customerForm(id){requireManager(actor);const c=id?customer(id):{};modal(id?'Customer details':'Add a fictional customer',`<form id="customer-form" data-id="${esc(id||'')}">${field('Customer or business name','name',c.name,'text','required maxlength="100"')}${select('Customer type','type',['Domestic','Commercial','End of tenancy'].map(x=>[x,x]),c.type||'Domestic')}${field('Fictional service address','address',c.address,'text','required maxlength="250"')}${field('Demo email (use example.com)','email',c.email,'email','maxlength="150"')}<label>Customer preferences<textarea name="notes" maxlength="1000">${esc(c.notes||'')}</textarea></label>${id?`<h3>Visit history</h3><div class="history">${state.jobs.filter(j=>j.customerId===id).slice().sort((a,b)=>b.date.localeCompare(a.date)).map(j=>`<p>${dateLabel(j.date)} · ${esc(j.time)} ${badge(j.status)}</p>`).join('')||'No visits yet.'}</div>${button('Archive customer','archive-customer',`data-id="${esc(id)}"`,'danger')}`:''}${formEnd(id?'Save customer':'Create customer')}`)}
function jobForm(id){requireManager(actor);const j=id?getJob(state,actor,id):{date:selectedDate,time:'09:00',duration:120,price:6500,round:'Birkdale round',repeat:'One-off',staffId:''};modal(id?'Edit this visit':'Plan a cleaning visit',`<form id="job-form" data-id="${esc(id||'')}">${select('Customer','customerId',state.customers.filter(c=>c.active).map(c=>[c.id,c.name]),j.customerId)}<div class="form-grid">${field('Date','date',j.date,'date','required')}${field('Start time','time',j.time,'time','required')}${field('Duration (minutes)','duration',j.duration,'number','required min="15" max="720" step="15"')}${field('Price excluding VAT (£)','price',(j.price/100).toFixed(2),'number','required min="0" max="100000" step="0.01"')}</div>${select('Assign team member','staffId',[['','Unassigned'],...state.staff.map(s=>[s.id,s.name])],j.staffId)}${field('Round or area','round',j.round,'text','required maxlength="80"')}${select('Repeats','repeat',['One-off','Weekly','Fortnightly','Four-weekly'].map(v=>[v,v]),j.repeat)}${id?'<p class="notice">Edits affect this visit only; existing later visits stay as booked.</p>':field('Number of visits to create (1–12)','count',1,'number','required min="1" max="12"')}<p class="muted">Overlaps and daily capacity are checked across every visit before anything is saved. Repeat series are finite; no background bookings.</p>${formEnd(id?'Save visit':'Book visit(s)')}`)}
function jobDetail(id){const j=getJob(state,actor,id),c=customer(j.customerId);modal(c.name,`<div class="detail-title">${badge(j.status)}<span>${esc(j.repeat)} · ${esc(j.round)}</span></div><div class="detail-meta"><div><small>WHEN</small><strong>${dateLabel(j.date)} · ${esc(j.time)}</strong><span>${j.duration/60} hours</span></div><div><small>ASSIGNED TO</small>${person(j.staffId)}</div></div><h3>Service address</h3><p>${esc(c.address)}</p><div class="notice"><strong>Customer instructions</strong><p>${esc(c.notes||'No specific instructions.')}</p></div><h3>Quality checklist <small>${j.checklist.filter(i=>i.done).length}/${j.checklist.length}</small></h3><div class="checklist">${j.checklist.map((item,i)=>`<label><input type="checkbox" data-check="${i}" data-id="${esc(id)}" ${item.done?'checked':''} ${j.status!=='In progress'?'disabled':''}><span>${esc(item.label)}</span></label>`).join('')}</div><label class="notes-label">Visit notes<textarea id="visit-note" maxlength="2000" ${['Cancelled','Completed'].includes(j.status)?'disabled':''}>${esc(j.notes)}</textarea></label>${!['Cancelled','Completed'].includes(j.status)?button('Save visit note','save-note',`data-id="${esc(id)}"`):''}<p id="form-error" class="form-error" role="alert"></p><div class="form-footer job-actions">${actor.role==='manager'&&j.status==='Scheduled'?button('Edit visit','edit-job',`data-id="${esc(id)}"`)+button('Cancel visit','cancel-job',`data-id="${esc(id)}"`,'danger'):''}${j.status==='Scheduled'?button('Start job →','start-job',`data-id="${esc(id)}"`,'primary'):j.status==='In progress'?button('Complete job ✓','complete-job',`data-id="${esc(id)}"`,'primary'):j.status==='Completed'&&actor.role==='manager'?(j.invoiceId?button('View invoice','invoice-detail',`data-id="${esc(j.invoiceId)}"`,'primary'):button('Create invoice →','invoice-job',`data-id="${esc(id)}"`,'primary')):''}</div>`)}
function invoiceForm(jobId){requireManager(actor);const list=state.jobs.filter(j=>j.status==='Completed'&&!j.invoiceId);if(!list.length){toast('Complete a job that has not yet been invoiced.');return}modal('Create a draft invoice',`<form id="invoice-form">${select('Completed visit','jobId',list.map(j=>[j.id,`${customer(j.customerId).name} · ${j.date} · ${money(j.price)}`]),jobId||list[0].id)}${select('VAT (only for VAT-registered suppliers)','vat',[["0","No VAT · 0%"],["20","Standard rate · 20%"]],'0')}<div class="notice">This creates a demo draft. It does not send an email, collect money, or constitute a valid business invoice. Payment terms: 14 days.</div>${formEnd('Create draft invoice')}`)}
function invoiceDetail(id){requireManager(actor);const i=state.invoices.find(i=>i.id===id);if(!i)throw Error('Invoice not found.');modal(i.number,`<article class="invoice-preview"><div class="invoice-letterhead"><strong>Fern & Co. Cleaning</strong><span>DEMONSTRATION DRAFT</span></div><p>Fictional supplier · no real trading address or VAT registration</p><div class="detail-meta"><div><small>BILL TO</small><strong>${esc(i.customerName)}</strong><span>${esc(i.address)}</span></div><div><small>INVOICE</small><strong>${esc(i.number)}</strong><span>Issued ${dateLabel(i.issued)}<br>Due ${dateLabel(i.due)}</span></div></div><p>${esc(i.description)}</p><dl class="invoice-totals"><div><dt>Subtotal</dt><dd>${money(i.net)}</dd></div><div><dt>VAT (${i.vat}%)</dt><dd>${money(i.tax)}</dd></div><div class="total"><dt>Total</dt><dd>${money(i.total)}</dd></div></dl>${badge(i.status)}<p class="muted">${i.paidOn?'Manual demo payment recorded '+dateLabel(i.paidOn):'No payment requested or processed.'}</p></article><p id="form-error" class="form-error" role="alert"></p><div class="form-footer">${button('Download draft','download-invoice',`data-id="${esc(id)}"`)}${i.status!=='Paid'?button('Record demo payment','pay-invoice',`data-id="${esc(id)}"`,'primary'):''}</div>`)}
function download(name,body,type){const url=URL.createObjectURL(new Blob([body],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function act(action,el){const id=el.dataset.id;switch(action){case'close':$('#modal').close();break;case'new-job':jobForm();break;case'edit-job':jobForm(id);break;case'new-customer':customerForm();break;case'customer-detail':customerForm(id);break;case'job-detail':jobDetail(id);break;case'filter':filter=el.dataset.value;render();break;case'prev-day':selectedDate=dayAdd(selectedDate,-1);render();break;case'next-day':selectedDate=dayAdd(selectedDate,1);render();break;case'today':selectedDate=TODAY;render();break;case'prev-week':weekStart=dayAdd(weekStart,-7);render();break;case'next-week':weekStart=dayAdd(weekStart,7);render();break;case'staff-view':actor={role:'staff',staffId:id};view='jobs';render();break;case'new-staff':requireManager(actor);modal('Add a fictional team member',`<form id="staff-form">${field('Full name','name','','text','required maxlength="100"')}${field('Role','role','Cleaning specialist','text','maxlength="100"')}${field('Daily working capacity (minutes)','capacity',480,'number','required min="60" max="720" step="15"')}${formEnd('Add team member')}`);break;case'start-job':case'complete-job':case'cancel-job':case'save-note':{const a={'start-job':'start','complete-job':'complete','cancel-job':'cancel','save-note':'note'}[action];if(a==='cancel'&&!confirm('Cancel this visit? Later visits in its series will stay booked.'))return;mutate(()=>{if(a==='complete'&&$('#visit-note'))updateJob(state,actor,id,'note',$('#visit-note').value);return updateJob(state,actor,id,a,a==='note'?$('#visit-note').value:undefined)});render();jobDetail(id);toast(a==='note'?'Visit note saved.':'Job updated.');break}case'archive-customer':if(confirm('Archive this customer? Completed history is kept.')){mutate(()=>archiveCustomer(state,actor,id));$('#modal').close();render();toast('Customer archived.')}break;case'new-invoice':invoiceForm();break;case'invoice-job':invoiceForm(id);break;case'invoice-detail':invoiceDetail(id);break;case'pay-invoice':mutate(()=>markPaid(state,actor,id));render();invoiceDetail(id);toast('Demo payment recorded. No money was collected.');break;case'download-invoice':{requireManager(actor);const i=state.invoices.find(i=>i.id===id);if(!i)throw Error('Invoice not found');download(i.number+'-DEMO.txt',`DEMONSTRATION DRAFT — NOT A VALID TAX INVOICE\nFern & Co. Cleaning (fictional supplier)\n${i.number}\nCustomer: ${i.customerName}\nAddress: ${i.address}\nIssued: ${i.issued}\nDue: ${i.due}\n${i.description}\nSubtotal: ${money(i.net)}\nVAT (${i.vat}%): ${money(i.tax)}\nTotal: ${money(i.total)}\nStatus: ${i.status}\nNo real payment requested.\n`,'text/plain');break}case'export-invoices':requireManager(actor);download('quenvira-demo-invoices.csv',csv([['Number','Customer','Issued','Due','Net GBP','VAT GBP','Total GBP','Status'],...state.invoices.map(i=>[i.number,i.customerName,i.issued,i.due,(i.net/100).toFixed(2),(i.tax/100).toFixed(2),(i.total/100).toFixed(2),i.status])]),'text/csv');break;case'export-customers':requireManager(actor);download('quenvira-demo-customers.csv',csv([['Name','Type','Address','Email','Notes','Active'],...state.customers.map(c=>[c.name,c.type,c.address,c.email,c.notes,c.active])]),'text/csv');break;case'export-json':requireManager(actor);download('quenvira-demo-backup.json',JSON.stringify(state,null,2),'application/json');break;case'reset':requireManager(actor);if(confirm('Reset this browser’s demo? All your edits will be removed. Download a backup first if you want to keep them.')){state=seed();persist();render();toast('Fictional demo restored.')}break;}}
function handleClick(e){const el=e.target.closest('[data-action]');if(!el)return;try{act(el.dataset.action,el)}catch(err){const error=$('#form-error');if($('#modal').open&&error)error.textContent=err.message;else toast(err.message)}}
function bindPage(){const date=$('#job-date');if(date)date.onchange=e=>{if(e.target.value){selectedDate=e.target.value;render()}};for(const id of ['job-search','customer-search']){const input=$('#'+id);if(input)input.addEventListener('input',e=>{search=e.target.value;const start=e.target.selectionStart;render();const next=$('#'+id);next.focus();if(next.type==='search')next.setSelectionRange(start,start)})}}
function bindModal(){const d=$('#modal');const form=d.querySelector('form');if(form)form.onsubmit=e=>{e.preventDefault();const values=Object.fromEntries(new FormData(form));try{let result;switch(form.id){case'customer-form':result=mutate(()=>saveCustomer(state,actor,values,form.dataset.id||undefined));break;case'job-form':values.price=Math.round(Number(values.price)*100);result=mutate(()=>saveJob(state,actor,values,form.dataset.id||undefined));break;case'staff-form':result=mutate(()=>addStaff(state,actor,values));break;case'invoice-form':result=mutate(()=>createInvoice(state,actor,values.jobId,Number(values.vat)));break}d.close();render();toast('Saved to this browser’s demonstration.');if(form.id==='invoice-form')invoiceDetail(result.id)}catch(err){$('#form-error').textContent=err.message}};d.querySelectorAll('[data-check]').forEach(input=>input.addEventListener('change',()=>{try{const note=$('#visit-note')?.value;mutate(()=>{if(note!==undefined&&note!==getJob(state,actor,input.dataset.id).notes)updateJob(state,actor,input.dataset.id,'note',note);updateJob(state,actor,input.dataset.id,'check',Number(input.dataset.check))});render();jobDetail(input.dataset.id)}catch(err){$('#form-error').textContent=err.message;input.checked=!input.checked}}));}
document.addEventListener('click',handleClick);$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}});
function route(){const target=location.hash.slice(1);view=['dashboard','schedule','jobs','customers','team','invoices','settings'].includes(target)?target:'dashboard';search='';filter='All';if($('#modal').open)$('#modal').close();render()}
window.addEventListener('hashchange',route);route();
